import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"LuaMapScriptExample","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/examples/LuaMapScriptExample/README.md","filePath":"Modders/examples/LuaMapScriptExample/README.md"}'),r={name:"Modders/examples/LuaMapScriptExample/README.md"};function c(i,e,d,n,p,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="luamapscriptexample" tabindex="-1">LuaMapScriptExample <a class="header-anchor" href="#luamapscriptexample" aria-label="Permalink to &quot;LuaMapScriptExample&quot;">​</a></h1><p>A complete, copy-and-rename example <strong>Lua map script</strong> mod. It generates a simple Perlin-noise island map: raises land, assigns continents, adds climate/mountains/coasts/ rivers, places one balanced starting location with luxury and strategic resources.</p><h2 id="how-lua-map-scripts-work" tabindex="-1">How Lua map scripts work <a class="header-anchor" href="#how-lua-map-scripts-work" aria-label="Permalink to &quot;How Lua map scripts work&quot;">​</a></h2><p>A mod that ships a <code>scripts/</code> folder with a <code>.lua</code> file defining <strong>both</strong> of these functions becomes a selectable map type in the new-game screen:</p><table tabindex="0"><thead><tr><th>Function</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GetMapScriptInfo()</code></td><td>Returns <code>{ name = &quot;...&quot;, description = &quot;...&quot; }</code> shown in the UI</td></tr><tr><td><code>GenerateMap(ctx)</code></td><td>Builds the map; returns <code>true</code> on success</td></tr></tbody></table><p>When the player picks <strong>Lua Generated</strong> as the map type and this script, the game creates an all-ocean <code>TileMap</code> of the configured size, calls <code>GenerateMap(ctx)</code> and normalizes the result against the ruleset. <code>ctx</code> exposes <code>params</code>, <code>seed</code>, <code>perlin</code>, <code>random</code>/<code>randomInt</code>, <code>log</code> and the <code>map</code> manipulation table (see the header comment in <code>scripts/mapScript.lua</code> for the full API list).</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><ol><li>Copy this folder into <code>UncivMods/</code> (or use the in-game mod import) and enable it.</li><li>Start a new game, set <strong>Map Type → Lua Generated</strong>, pick &quot;Lua Example: Perlin Islands&quot;.</li><li>Pick your map size/shape, then start the game.</li></ol><p>The example intentionally uses a small API subset; the engine provides many more helpers (<code>floodFill</code>, <code>generateIce</code>, <code>strategicBalanceStarts</code>, tile-level writes...) that are exercised by the test suite in <code>tests/src/com/unciv/logic/scripting/LuaMapGenAPITests.kt</code>.</p>',9)])])}const h=t(r,[["render",c]]);export{u as __pageData,h as default};
